async function loadMaterialsSummary(){const homework=document.querySelector('[data-homework-summary]'),notes=document.querySelector('[data-notes-summary]');if(!homework||!notes)return;homework.textContent='Загружаем задание…';notes.textContent='Загружаем конспект…';try{const [homeData,noteData]=await Promise.all(['homework','notes'].map(async category=>{const response=await fetch('/api/materials?limit=1&content='+category,{cache:'no-store'});if(!response.ok)throw Error();return response.json()}));const render=(target,category)=>{const row=(category==='homework'?homeData:noteData).items[0];target.replaceChildren();if(!row){target.textContent=category==='homework'?'Новых домашних заданий нет.':'Конспекты пока не добавлены.';return}const date=new Date(row.starts_at).toLocaleDateString('ru-RU',{timeZone:row.timezone,dateStyle:'long'}),p=document.createElement('p');p.textContent='Урок '+date+' · '+(row.topic||'Математика');target.append(p);const text=document.createElement('p');text.className='material-summary-text';const value=row[category];text.textContent=value.length>400?value.slice(0,400)+'…':value||'Прикреплены файлы.';target.append(text);if(category==='homework'){const due=document.createElement('p');due.textContent=row.due_mode==='manual'?'К дате: '+String(row.due_date).slice(0,10).split('-').reverse().join('.'):row.next_lesson_at?'К следующему занятию: '+new Date(row.next_lesson_at).toLocaleString('ru-RU',{timeZone:row.timezone,dateStyle:'short',timeStyle:'short'}):'К следующему занятию — дата пока не назначена';target.append(due)}const a=document.createElement('a');a.href='materials.html?lesson_id='+row.lesson_id;a.className='action-link';a.textContent='Открыть материалы урока';target.append(a)};render(homework,'homework');render(notes,'notes')}catch{homework.textContent='Не удалось загрузить задания. Откройте историю и попробуйте обновить.';notes.textContent='Конспекты временно недоступны.'}}
